}

impl std::fmt::Display for AngleUnit {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            AngleUnit::Degree => write!(f, "degree"),
            AngleUnit::Radian => write!(f, "radian"),
            AngleUnit::Gradian => write!(f, "gradian"),
        }
    }
