                // For "0x10" case, after number "0", we are now at 'x', ident "x" then digit '1' -> would trigger above
                // For "epi2" case, ident would be "epi" then digit '2' -> triggers
                // For "pisin3", ident "pisin" + digit '3' -> triggers
                // Need also handle case where ident is unknown but followed by '(' -> unknown function error should be Syntax Error: Unknown function 'ident'
                // That will be handled later in parser, not here
                // So for now, push Ident token
                tokens.push(Token::Ident(ident));
            }
            i = j;
        } else if c == '_' {
            tokens.push(Token::Underscore);
            i+=1;
        } else if c == '+' {
            tokens.push(Token::Plus);
            i+=1;
        } else if c == '-' {
            tokens.push(Token::Minus);
            i+=1;
        } else if c == '*' {
            if i+1 < chars.len() && chars[i+1]=='*' {
                tokens.push(Token::Caret);
                i+=2;
            } else {
                tokens.push(Token::Star);
                i+=1;
            }
        } else if c == '/' {
            tokens.push(Token::Slash);
            i+=1;
        } else if c == '^' {
            tokens.push(Token::Caret);
            i+=1;
        } else if c == '!' {
            tokens.push(Token::Bang);
            i+=1;
        } else if c == '(' {
            tokens.push(Token::LParen);
            i+=1;
        } else if c == ')' {
            tokens.push(Token::RParen);
            i+=1;
        } else if c == ',' {
            tokens.push(Token::Comma);
            i+=1;
        } else {
            // Unexpected token/character
            // For characters like ';', '@', '#', etc.
            // Determine if it's token-like
            // Use "Unexpected token: 'X'" for symbols, "Unexpected character" for letters/digits?
            // For now, use Unexpected token
            if c.is_ascii_alphanumeric() {
                // collect sequence?
                let mut seq = String::new();
                seq.push(c);
                let mut k = i+1;
                while k < chars.len() && chars[k].is_ascii_alphanumeric() {
                    seq.push(chars[k]);
                    k+=1;
                }
                return Err(format!("Syntax Error: Unexpected character '{}'", seq));
            } else {
                return Err(format!("Syntax Error: Unexpected token: '{}'", c));
            }
        }
    }
    Ok(tokens)
}

fn insert_implicit_mul(tokens: Vec<Token>) -> Vec<Token> {
    if tokens.is_empty() { return tokens; }
    let mut res = Vec::new();
    for idx in 0..tokens.len() {
        let tok = tokens[idx].clone();
        res.push(tok.clone());
        if idx+1 >= tokens.len() { break; }
        let next = &tokens[idx+1];
        let left_is = match &tok {
            Token::Number(_) => true,
            Token::ConstPi => false, // actually true for some cases? But we need to handle per rules
            Token::ConstE => false,
            Token::Underscore => false,
            Token::RParen => true,
            Token::Bang => false,
            _ => false,
        };
        // More precise rules
        let insert = match (&tok, next) {
            (Token::Number(_), Token::LParen) => true,
            (Token::Number(_), Token::Func(_)) => true,
            (Token::Number(_), Token::ConstPi) => true,
            (Token::Number(_), Token::ConstE) => true,
            (Token::Number(_), Token::Underscore) => true,
            (Token::ConstPi, Token::Number(_)) => true,
            (Token::ConstE, Token::Number(_)) => true,
            (Token::RParen, Token::LParen) => true,
            // Function result is RParen, so RParen->LParen already
            // Also RParen->Number? No
            // RParen->Const? No
            // RParen->Func? No
            // Number->Underscore etc already
            _ => false,
        };
        if insert {
            res.push(Token::Star);
        }
    }
    res
}

#[derive(Debug)]
struct Parser {
    tokens: Vec<Token>,
    pos: usize,
    prev_ans: Option<f64>,
    angle: AngleUnit,
}

impl Parser {
    fn peek(&self) -> Option<&Token> {
        self.tokens.get(self.pos)
    }
    fn consume(&mut self) -> Option<Token> {
        if self.pos < self.tokens.len() {
            let t = self.tokens[self.pos].clone();
            self.pos+=1;
            Some(t)
        } else { None }
    }
    fn expect(&mut self, expected: &Token) -> Result<(), String> {
        if let Some(t) = self.peek() {
            if std::mem::discriminant(t) == std::mem::discriminant(expected) {
                self.consume();
                Ok(())
            } else {
                Err("Syntax Error: Mismatched parentheses!".to_string())
            }
        } else {
            Err("Syntax Error: Mismatched parentheses!".to_string())
        }
    }
}

fn parse_expression(parser: &mut Parser) -> Result<f64, String> {
    let mut left = parse_term(parser)?;
    while let Some(tok) = parser.peek() {
        match tok {
            Token::Plus => { parser.consume(); let right = parse_term(parser)?; left = left + right; if left.is_infinite() { return Err(format!("Error: to large to process! Max value: {}", MAX_STR)); } },
            Token::Minus => { parser.consume(); let right = parse_term(parser)?; left = left - right; if left.is_infinite() { return Err(format!("Error: to large to process! Max value: {}", MAX_STR)); } },
            _ => break,
        }
    }
    Ok(left)
}

fn parse_term(parser: &mut Parser) -> Result<f64, String> {
    let mut left = parse_factor(parser)?;
    while let Some(tok) = parser.peek() {
        match tok {
            Token::Star => { parser.consume(); let right = parse_factor(parser)?; left = left * right; if left.is_infinite() { return Err(format!("Error: to large to process! Max value: {}", MAX_STR)); } },
            Token::Slash => { parser.consume(); let right = parse_factor(parser)?; if right == 0.0 { return Err("Math Error: Divide by zero error!".to_string()); } left = left / right; if left.is_infinite() { return Err(format!("Error: to large to process! Max value: {}", MAX_STR)); } },
            _ => break,
        }
    }
    Ok(left)
}

fn parse_factor(parser: &mut Parser) -> Result<f64, String> {
    // Factor is Unary { ^ Unary } right associative
    let mut left = parse_unary(parser)?;
    if let Some(Token::Caret) = parser.peek() {
        parser.consume();
        let right = parse_factor(parser)?; // right associative
        // handle pow
        // Check domain for negative base with non-integer exponent? We'll compute and check NaN
        let res = left.powf(right);
        if res.is_nan() {
            return Err("Domain Error: Out of bounds!".to_string());
        }
        if res.is_infinite() {
            return Err(format!("Error: to large to process! Max value: {}", MAX_STR));
        }
        // Also check overflow for large exponent
        left = res;
    }
    Ok(left)
}

fn parse_unary(parser: &mut Parser) -> Result<f64, String> {
    if let Some(tok) = parser.peek() {
        match tok {
            Token::Plus => { parser.consume(); return parse_unary(parser); },
            Token::Minus => { parser.consume(); let v = parse_unary(parser)?; let res = -v; if res.is_infinite() { return Err(format!("Error: to large to process! Max value: {}", MAX_STR)); } return Ok(res); },
            _ => {},
        }
    }
    parse_postfix(parser)
}

fn parse_postfix(parser: &mut Parser) -> Result<f64, String> {
    let mut val = parse_primary(parser)?;
    while let Some(Token::Bang) = parser.peek() {
        parser.consume();
        // factorial
        if val < 0.0 || val.fract() != 0.0 {
            return Err("Domain Error: Out of bounds!".to_string());
        }
        let n = val as u64;
        // compute factorial
        let mut res: f64 = 1.0;
        for i in 2..=n {
            res *= i as f64;
            if res.is_infinite() {
                return Err(format!("Error: to large to process! Max value: {}", MAX_STR));
            }
        }
        // Check overflow for large n (like 1000! already huge but within? 1000! >1e2567 => inf => already caught)
        // But original for 1000! gave overflow error, we already return overflow
        val = res;
    }
    Ok(val)
}

fn parse_primary(parser: &mut Parser) -> Result<f64, String> {
    let tok = parser.peek().cloned();
    match tok {
        Some(Token::Number(v)) => { parser.consume(); if v.is_infinite() { return Err(format!("Error: to large to process! Max value: {}", MAX_STR)); } Ok(v) },
        Some(Token::ConstPi) => { parser.consume(); Ok(std::f64::consts::PI) },
        Some(Token::ConstE) => { parser.consume(); Ok(std::f64::consts::E) },
        Some(Token::Underscore) => {
            parser.consume();
            if let Some(prev) = parser.prev_ans {
                Ok(prev)
            } else {
                // For command mode, underscore is 0? But parser is same, we need to check context
                // In REPL, prev is None => error "Syntax Error: No previous answer!"
                // In command mode, we set prev_ans Some(0.0)
                Err("Syntax Error: No previous answer!".to_string())
            }
        },
        Some(Token::Func(name)) => {
            let func_name = name.clone();
            parser.consume();
            // Expect '('
            match parser.peek() {
                Some(Token::LParen) => {},
                _ => return Err(format!("Syntax Error: Function '{}' expected parentheses", func_name)),
            }
            parser.consume(); // '('
            // Parse args
            let mut args = Vec::new();
            // Check for empty args case: if next is RParen -> no args
            if let Some(Token::RParen) = parser.peek() {
                // empty
            } else {
                // Parse first arg
                // Need to handle case where there's a leading comma or ",)"
                // Check for leading comma
                if let Some(Token::Comma) = parser.peek() {
                    return Err(format!("Parser Error: To few arguments for function, need {}", if is_one_arg_func(&func_name) {1} else {2}));
                }
                let first = parse_expression(parser)?;
                args.push(first);
                while let Some(Token::Comma) = parser.peek() {
                    parser.consume();
                    // Check for trailing comma like "sin(30,)" -> original succeeded with 0.5? Actually sin(30,) gave 0.5. So trailing comma may be ignored?
                    // But sin(30,2) gave too many operators, not trailing comma
                    // For sin(30,) they gave success, so we should allow trailing comma with no arg? Or treat as missing arg -> ignore?
                    // Let's see: sin(30,) with our parser, after comma, we try to parse expression, next is RParen, we would error. But original gave success, so they ignore trailing comma.
                    if let Some(Token::RParen) = parser.peek() {
                        break;
                    }
                    if let Some(Token::Comma) = parser.peek() {
                        // two commas in a row -> indicates missing arg
                        return Err(format!("Parser Error: To few arguments for function, need {}", if is_one_arg_func(&func_name) {1} else {2}));
                    }
                    let next_arg = parse_expression(parser)?;
                    args.push(next_arg);
                }
            }
            // Expect ')'
            match parser.peek() {
                Some(Token::RParen) => { parser.consume(); },
                _ => return Err("Syntax Error: Mismatched parentheses!".to_string()),
            }
            // Validate arg count
            if is_one_arg_func(&func_name) {
                if args.len() < 1 {
                    return Err(format!("Parser Error: To few arguments for function, need 1"));
                }
                if args.len() > 1 {
                    return Err("Parser Error: Too many operators, too few operands".to_string());
                }
            } else if is_two_arg_func(&func_name) {
                if args.len() < 2 {
                    return Err(format!("Parser Error: To few arguments for function, need 2"));
                }
                if args.len() > 2 {
                    return Err("Parser Error: Too many operators, too few operands".to_string());
                }
            }
            // Evaluate
            eval_func(&func_name, &args, parser.angle)
        },
        Some(Token::Ident(name)) => {
            // Unknown function or variable
            // Check if next is '(' -> unknown function
            let ident_clone = name.clone();
            // Peek next token
            let next_is_lparen = if parser.pos+1 < parser.tokens.len() {
                matches!(parser.tokens[parser.pos+1], Token::LParen)
            } else { false };
            if next_is_lparen {
                return Err(format!("Syntax Error: Unknown function '{}'", ident_clone));
            } else {
                // For unknown ident without '(', treat as parser error Too many operators
                return Err("Parser Error: Too many operators, too few operands".to_string());
            }
        },
        Some(Token::LParen) => {
            parser.consume();
            let val = parse_expression(parser)?;
            match parser.peek() {
                Some(Token::RParen) => { parser.consume(); Ok(val) },
                _ => Err("Syntax Error: Mismatched parentheses!".to_string()),
            }
        },
        Some(Token::RParen) => {
            // This shouldn't happen at primary, but if we encounter RParen unexpected, it's mismatched
            Err("Syntax Error: Mismatched parentheses!".to_string())
        },
        Some(Token::Comma) => {
            Err("Syntax Error: Mismatched parentheses!".to_string())
        },
        Some(Token::Plus) | Some(Token::Minus) | Some(Token::Star) | Some(Token::Slash) | Some(Token::Caret) | Some(Token::Bang) => {
            Err("Parser Error: Too many operators, too few operands".to_string())
        },
        None => Err("Parser Error: Too many operators, too few operands".to_string()),
    }
}

fn eval_func(name: &str, args: &[f64], angle: AngleUnit) -> Result<f64, String> {
    let to_rad = |x: f64| {
        match angle {
            AngleUnit::Degree => x * std::f64::consts::PI / 180.0,
            AngleUnit::Radian => x,
            AngleUnit::Gradian => x * std::f64::consts::PI / 180.0, // same as degree to replicate bug
        }
    };
    let res = match name {
        "sin" => {
            let x = args[0];
            let r = to_rad(x);
            r.sin()
        },
        "cos" => {
            let x = args[0];
            let r = to_rad(x);
            r.cos()
        },
        "tan" => {
            let x = args[0];
            let r = to_rad(x);
            r.tan()
        },
        "csc" => {
            let x = args[0];
            let r = to_rad(x);
            let s = r.sin();
            if s.abs() < 1e-12 { return Err("Domain Error: Out of bounds!".to_string()); }
            1.0 / s
        },
        "sec" => {
            let x = args[0];
            let r = to_rad(x);
            let c = r.cos();
            if c.abs() < 1e-12 {
                // For sec(90) original gave huge not error, but for 90 exactly cos ~6e-17, not <1e-12? Actually cos 90 deg = 6e-17 <1e-12 true, but they gave huge not error. So threshold maybe smaller
                // Let's check: cos 90 deg = 6.123e-17, which is <1e-12, but they didn't error. So we should not error for that? Maybe they check exactly 0?
                // For csc(0) sin 0 =0 exactly, error. For sec(90) cos not exactly 0 due to floating, so they compute huge.
                // So we should check if s ==0.0 exactly?
                // But for csc(0) sin 0 is 0 exactly, error.
                // For cot(0) sin 0 =0 error.
                // So check exact zero?
                // We'll check if s ==0.0
                // But for floating, sin(pi) rad = 0 but may be 1e-16 not zero.
                // We'll check abs < 1e-12 as error for csc(0) where sin 0 =0 exactly, so passes.
                // For sec(90) where cos ~6e-17, abs <1e-12 would trigger error but original didn't. So we need looser threshold.
                // Let's use exact zero check
                // Actually s for 90 deg = cos(90* pi/180)= cos(1.570...)=6e-17 not zero, so not error
                // So we should check if s ==0.0
            }
            if c == 0.0 { return Err("Domain Error: Out of bounds!".to_string()); }
            1.0 / c
        },
        "cot" => {
            let x = args[0];
            let r = to_rad(x);
            let s = r.sin();
            if s == 0.0 { return Err("Domain Error: Out of bounds!".to_string()); }
            let c = r.cos();
            c / s
        },
        "sinh" => args[0].sinh(),
        "cosh" => args[0].cosh(),
        "tanh" => args[0].tanh(),
        "asin" => {
            let x = args[0];
            if x < -1.0 || x > 1.0 { return Err("Domain Error: Out of bounds!".to_string()); }
            x.asin()
        },
        "acos" => {
            let x = args[0];
            if x < -1.0 || x > 1.0 { return Err("Domain Error: Out of bounds!".to_string()); }
            x.acos()
        },
        "atan" => args[0].atan(),
        "acsc" => {
            let x = args[0];
            if x.abs() < 1.0 { return Err("Domain Error: Out of bounds!".to_string()); }
            (1.0/x).asin()
        },
        "asec" => {
            let x = args[0];
            if x.abs() < 1.0 { return Err("Domain Error: Out of bounds!".to_string()); }
            (1.0/x).acos()
        },
        "acot" => {
            let x = args[0];
            if x == 0.0 { return Ok(std::f64::consts::PI/2.0); }
            (1.0/x).atan()
        },
        "ln" => {
            let x = args[0];
            if x <= 0.0 { return Err("Domain Error: Out of bounds!".to_string()); }
            x.ln()
        },
        "log2" => {
            let x = args[0];
            if x <= 0.0 { return Err("Domain Error: Out of bounds!".to_string()); }
            x.log2()
        },
        "log10" => {
            let x = args[0];
            if x <= 0.0 { return Err("Domain Error: Out of bounds!".to_string()); }
            x.log10()
        },
        "sqrt" => {
            let x = args[0];
            if x < 0.0 { return Err("Domain Error: Out of bounds!".to_string()); }
            x.sqrt()
        },
        "ceil" => args[0].ceil(),
        "floor" => args[0].floor(),
        "abs" => args[0].abs(),
        "exp" => {
            let x = args[0];
            let r = x.exp();
            if r.is_infinite() { return Err("Domain Error: Out of bounds!".to_string()); }
            r
        },
        "deg" => args[0] * 180.0 / std::f64::consts::PI,
        "rad" => args[0] * std::f64::consts::PI / 180.0,
        "log" => {
            let x = args[0];
            let base = args[1];
            if x <= 0.0 || base <= 0.0 || base == 1.0 { return Err("Domain Error: Out of bounds!".to_string()); }
            x.log(base)
        },
        "nroot" => {
            let x = args[0];
            let n = args[1];
            if n == 0.0 { return Err("Domain Error: Out of bounds!".to_string()); }
            if x < 0.0 { return Err("Domain Error: Out of bounds!".to_string()); }
            // nroot may be 1/n
            x.powf(1.0/n)
        },
        _ => return Err(format!("Syntax Error: Unknown function '{}'", name)),
    };
    if res.is_nan() {
        return Err("Domain Error: Out of bounds!".to_string());
    }
    if res.is_infinite() {
        return Err(format!("Error: to large to process! Max value: {}", MAX_STR));
    }
    // Check overflow beyond max
    if res.abs() > 1.7976931348623157e308 {
        return Err(format!("Error: to large to process! Max value: {}", MAX_STR));
    }
    Ok(res)
}

fn balance_parens(s: &str) -> Result<String, String> {
    let open = s.chars().filter(|&c| c=='(').count();
    let close = s.chars().filter(|&c| c==')').count();
    if close > open {
        Err("Syntax Error: Mismatched parentheses!".to_string())
    } else if open > close {
        Ok(format!("{}{}", s, ")".repeat(open-close)))
    } else {
        Ok(s.to_string())
    }
}

fn eval_input(input: &str, prev_ans: Option<f64>, angle: AngleUnit) -> Result<f64, String> {
    let trimmed = input.trim();
    if trimmed.is_empty() {
        // For empty input, what to do? In REPL, empty line maybe ignored? In command mode, empty input should not happen
        // Return error? But original for empty input in command mode gave no output? Actually we saw ./executable "" gave empty output with rc0
        // So we should treat empty as no evaluation
        return Err("EMPTY".to_string());
    }
    // Check for unexpected characters that are not part of valid tokens but are symbols like ';' etc.
    // Lex will handle
    let balanced = balance_parens(trimmed)?;
    let tokens = lex(&balanced)?;
    if tokens.is_empty() {
        return Err("Parser Error: Too many operators, too few operands".to_string());
    }
    let with_mul = insert_implicit_mul(tokens);
    // Check for remaining unexpected tokens like ';' handled in lex
    // Now parse
    let mut parser = Parser { tokens: with_mul, pos: 0, prev_ans, angle };
    let result = parse_expression(&mut parser)?;
    // Ensure all tokens consumed
    if parser.pos < parser.tokens.len() {
        // Check what leftover token is
        match &parser.tokens[parser.pos] {
            Token::RParen => return Err("Syntax Error: Mismatched parentheses!".to_string()),
            Token::Comma => return Err("Syntax Error: Mismatched parentheses!".to_string()),
            _ => return Err("Parser Error: Too many operators, too few operands".to_string()),
        }
    }
    Ok(result)
}

fn main() {
    let cli = Cli::parse();
    let fix = cli.fix;
    let base = cli.base;
    let angle = cli.angle_unit;
    if let Some(input) = cli.input {
        // Command mode
        // For command mode, underscore is 0
        let prev = Some(0.0);
        match eval_input(&input, prev, angle) {
            Ok(val) => {
                // Check for empty?
                if format!("{}", val) == "EMPTY" { std::process::exit(0); }
                let out = format_result(val, base, fix);
                println!("{}", out);
            },
            Err(e) => {
                if e == "EMPTY" { std::process::exit(0); }
                eprintln!("{}", e);
                std::process::exit(1);
            }
        }
    } else {
        // REPL mode
        // Determine history and cache paths
        let data_dir = dirs::data_dir().unwrap_or_else(|| PathBuf::from("."));
        let cache_dir = dirs::cache_dir().unwrap_or_else(|| PathBuf::from("."));
        let history_path = data_dir.join("eva").join("history.txt");
        let cache_path = cache_dir.join("eva").join("previous_ans.txt");
        // Check history existence
        let history_exists = history_path.exists();
        let mut prev_ans: Option<f64> = None;
        if !history_exists {
            println!("No previous history.");
        }
        // Ensure directories exist
        if let Some(parent) = history_path.parent() { let _ = fs::create_dir_all(parent); }
        if let Some(parent) = cache_path.parent() { let _ = fs::create_dir_all(parent); }
        // REPL loop
        let stdin = io::stdin();
        let mut stdout = io::stdout();
        let mut history_content = if history_exists {
            fs::read_to_string(&history_path).unwrap_or_default()
        } else {
            String::new()
        };
        let mut has_written_header = history_content.starts_with("#V2");
        // If not exists, we will create with header on first write
        for line in stdin.lock().lines() {
            let line = match line { Ok(l) => l, Err(_) => break };
            let trimmed = line.trim();
            if trimmed.is_empty() {
                continue;
            }
            // Handle previous answer loading? We keep in memory
            match eval_input(trimmed, prev_ans, angle) {
                Ok(val) => {
                    let out = format_result(val, base, fix);
                    println!("{}", out);
                    // Update prev_ans
                    prev_ans = Some(val);
                    // Write to cache file
                    let cache_str = if val.fract() == 0.0 && val.abs() < 1e15 {
                        // Use integer representation without .0 ? But earlier cache for 5 was "5", for 1000000 was "1000000", for 0.333... was "0.3333333333"
                        // For integer values, they store without decimal? For 5, they stored "5", not "5.0"
                        // For 1/3, they stored "0.3333333333" (which is with decimals)
                        // So we need to store as default Display without trailing zeros? Let's use Rust's default to_string but remove trailing zeros?
                        // For now, store as val.to_string() but need to decide
                        // Let's mimic: if val is integer, store as integer without decimal, else store as with default?
                        // Test: val=5.0 => to_string gives "5", matches
                        // val=0.3333333333 => to_string gives "0.3333333333" matches
                        // val=1.5 => "1.5" matches
                        // val=1000000.0 => "1000000" matches
                        format!("{}", val)
                    } else {
                        // For non-integer that would be like 0.3, format as is
                        // But for 0.3, to_string gives "0.3"
                        // For large 5, same
                        // So just use default
                        format!("{}", val)
                    };
                    // But need to handle that cache for 0.1+0.2 with fix 10 gave "0.3" not "0.30000000000000004" due to floating error
