use clap::{Arg, Command};
use std::path::PathBuf;
use std::fs;
use std::io::{self, BufRead};

const MAX_STR: &str = "";

fn to_base(mut n: u64, base: u32) -> String {
    if n == 0 { return "0".to_string(); }
    let digits = b"0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ";
    let mut s = String::new();
    while n > 0 {
        s.push(digits[(n % base as u64) as usize] as char);
        n /= base as u64;
    }
    s.chars().rev().collect()
}

fn insert_commas(s: &str) -> String {
    let sign = if s.starts_with('-') { "-" } else { "" };
    let core = if s.starts_with('-') { &s[1..] } else { s };
    let rev: Vec<char> = core.chars().rev().collect();
    let mut out_rev = String::new();
    for (i,ch) in rev.iter().enumerate() {
        if i>0 && i%3==0 {
            out_rev.push(',');
        }
        out_rev.push(*ch);
    }
    let mut res: String = out_rev.chars().rev().collect();
    if !sign.is_empty() {
        res = format!("{}{}", sign, res);
    }
    res
}

fn format_result(value: f64, base: u32, fix: u32) -> String {
    if base == 10 {
        let s = format!("{:.prec$}", value, prec=fix as usize);
        if let Some(dot_pos) = s.find('.') {
            let int_part = &s[..dot_pos];
            let frac_part = &s[dot_pos+1..];
            let int_with_commas = insert_commas(int_part);
            format!("{}.{}", int_with_commas, frac_part)
        } else {
            insert_commas(&s)
        }
    } else {
        let is_neg = value.is_sign_negative();
        let abs_val = value.abs();
        let int_part_val = abs_val.trunc();
        let int_str = if int_part_val == 0.0 {
            "0".to_string()
        } else {
            if int_part_val <= u64::MAX as f64 && int_part_val.fract() == 0.0 {
                to_base(int_part_val as u64, base)
            } else {
                let mut n = int_part_val;
                let mut digits = Vec::new();
                let dchars = b"0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ";
                while n >= 1.0 {
                    let rem = (n % base as f64).floor() as usize;
                    digits.push(dchars[rem] as char);
                    n = (n / base as f64).floor();
                    if digits.len() > 1000 { break; }
                }
                if digits.is_empty() { "0".to_string() } else { digits.iter().rev().collect() }
            }
        };
        let signed_int_str = if is_neg {
            format!("-{}", int_str)
        } else {
            int_str.clone()
        };
        let mut int_with_commas2 = insert_commas(&signed_int_str);
        if int_with_commas2.len() < 13 {
            let mut padded = format!("{:>13}", int_with_commas2);
            let mut chars: Vec<char> = padded.chars().collect();
            for pos in [1usize,5,9] {
                if pos < chars.len() && chars[pos]==' ' {
                    chars[pos]=',';
                }
            }
            int_with_commas2 = chars.into_iter().collect();
        }
        let mut frac = abs_val.fract();
        if frac > 0.9999999999995 {
            frac = 0.0;
        }
        if frac < 1e-12 {
            return format!("{}.0", int_with_commas2);
        }
        let mut digits = Vec::new();
        let mut f = frac;
        for _ in 0..fix {
            f *= base as f64;
            let mut d = (f + 1e-12).floor() as u32;
            if d >= base { d = base-1; }
            digits.push(d);
            f -= d as f64;
            if f.abs() < 1e-12 {
                break;
            }
        }
        let digit_chars = b"0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ";
        let mut frac_str: String = digits.iter().map(|&d| digit_chars[d as usize] as char).collect();
        while frac_str.len() > 1 && frac_str.ends_with('0') {
            frac_str.pop();
        }
        if frac_str.is_empty() { frac_str = "0".to_string(); }
        format!("{}.{}", int_with_commas2, frac_str)
    }
}

#[derive(Clone, Debug)]
enum Token {
    Number(f64),
    ConstPi,
    ConstE,
    Underscore,
    Ident(String),
    Func(String),
    Plus,
    Minus,
    Star,
    Slash,
    Caret,
    Bang,
    LParen,
    RParen,
    Comma,
}

fn is_one_arg_func(name: &str) -> bool {
    matches!(name, "sin"|"cos"|"tan"|"csc"|"sec"|"cot"|"sinh"|"cosh"|"tanh"|"asin"|"acos"|"atan"|"acsc"|"asec"|"acot"|"ln"|"log2"|"log10"|"sqrt"|"ceil"|"floor"|"abs"|"exp"|"deg"|"rad")
}
fn is_two_arg_func(name: &str) -> bool {
    matches!(name, "log"|"nroot")
}
fn is_func(name: &str) -> bool {
    is_one_arg_func(name) || is_two_arg_func(name)
}

fn lex(input: &str) -> Result<Vec<Token>, String> {
    let s: String = input.chars().filter(|c| !c.is_whitespace()).collect();
    if s.is_empty() {
        return Ok(vec![]);
    }
    let chars: Vec<char> = s.chars().collect();
    let mut i = 0;
    let mut tokens = Vec::new();
    while i < chars.len() {
        let c = chars[i];
        if c.is_ascii_digit() || c == '.' {
            let start = i;
            let mut has_dot = false;
            let mut j = i;
            while j < chars.len() {
                let ch = chars[j];
                if ch.is_ascii_digit() {
                    j+=1;
                } else if ch == '.' {
                    if has_dot { break; } else { has_dot=true; j+=1; }
                } else { break; }
            }
            if j == start {
                return Err(format!("Syntax Error: Unexpected token: '{}'", c));
            }
            let num_str: String = chars[start..j].iter().collect();
            if num_str == "." {
                return Err(format!("Syntax Error: Unexpected token: '.'"));
            }
            match num_str.parse::<f64>() {
                Ok(v) => tokens.push(Token::Number(v)),
                Err(_) => return Err(format!("Syntax Error: Unexpected character '{}'", num_str)),
            }
            i = j;
        } else if c.is_ascii_alphabetic() {
            let start = i;
            let mut j = i;
            while j < chars.len() && chars[j].is_ascii_alphabetic() { j+=1; }
            let ident: String = chars[start..j].iter().collect();
            if ident == "pi" {
                tokens.push(Token::ConstPi);
            } else if ident == "e" {
                tokens.push(Token::ConstE);
            } else if is_func(&ident) {
                tokens.push(Token::Func(ident));
            } else {
                if j < chars.len() && chars[j].is_ascii_digit() {
                    let mut k = j;
                    while k < chars.len() && chars[k].is_ascii_digit() { k+=1; }
                    let seq: String = chars[start..k].iter().collect();
                    return Err(format!("Syntax Error: Unexpected character '{}'", seq));
                }
                tokens.push(Token::Ident(ident));
            }
            i = j;
        } else if c == '_' {
            tokens.push(Token::Underscore);
            i+=1;
        } else if c == '+' {
            tokens.push(Token::Plus); i+=1;
        } else if c == '-' {
            tokens.push(Token::Minus); i+=1;
        } else if c == '*' {
            if i+1 < chars.len() && chars[i+1]=='*' {
                tokens.push(Token::Caret); i+=2;
            } else { tokens.push(Token::Star); i+=1; }
        } else if c == '/' {
            tokens.push(Token::Slash); i+=1;
        } else if c == '^' {
            tokens.push(Token::Caret); i+=1;
        } else if c == '!' {
            tokens.push(Token::Bang); i+=1;
        } else if c == '(' {
            tokens.push(Token::LParen); i+=1;
        } else if c == ')' {
            tokens.push(Token::RParen); i+=1;
        } else if c == ',' {
            tokens.push(Token::Comma); i+=1;
        } else {
            if c.is_ascii_alphanumeric() {
                let mut seq = String::new();
                seq.push(c);
                let mut k = i+1;
                while k < chars.len() && chars[k].is_ascii_alphanumeric() { seq.push(chars[k]); k+=1; }
                return Err(format!("Syntax Error: Unexpected character '{}'", seq));
            } else {
                return Err(format!("Syntax Error: Unexpected token: '{}'", c));
            }
        }
    }
    Ok(tokens)
}

fn insert_implicit_mul(tokens: Vec<Token>) -> Vec<Token> {
    if tokens.is_empty() { return tokens; }
    let mut res = Vec::new();
    for idx in 0..tokens.len() {
        let tok = tokens[idx].clone();
        res.push(tok.clone());
        if idx+1 >= tokens.len() { break; }
        let next = &tokens[idx+1];
        let insert = match (&tok, next) {
            (Token::Number(_), Token::LParen) => true,
            (Token::Number(_), Token::Func(_)) => true,
            (Token::Number(_), Token::ConstPi) => true,
            (Token::Number(_), Token::ConstE) => true,
            (Token::Number(_), Token::Underscore) => true,
            (Token::ConstPi, Token::Number(_)) => true,
            (Token::ConstE, Token::Number(_)) => true,
            (Token::RParen, Token::LParen) => true,
            _ => false,
        };
        if insert { res.push(Token::Star); }
    }
    res
}

struct Parser {
    tokens: Vec<Token>,
    pos: usize,
    prev_ans: Option<f64>,
    angle: i32, // 0 degree, 1 radian, 2 gradian
}

impl Parser {
    fn peek(&self) -> Option<&Token> { self.tokens.get(self.pos) }
    fn consume(&mut self) -> Option<Token> {
        if self.pos < self.tokens.len() {
            let t = self.tokens[self.pos].clone();
            self.pos+=1;
            Some(t)
        } else { None }
    }
}

fn parse_expression(parser: &mut Parser) -> Result<f64, String> {
    let mut left = parse_term(parser)?;
    while let Some(tok) = parser.peek() {
        match tok {
            Token::Plus => { parser.consume(); let right = parse_term(parser)?; left = left + right; if left.is_infinite() { return Err(format!("Error: to large to process! Max value: {}", MAX_STR)); } },
            Token::Minus => { parser.consume(); let right = parse_term(parser)?; left = left - right; if left.is_infinite() { return Err(format!("Error: to large to process! Max value: {}", MAX_STR)); } },
            _ => break,
        }
    }
    Ok(left)
}

fn parse_term(parser: &mut Parser) -> Result<f64, String> {
    let mut left = parse_factor(parser)?;
    while let Some(tok) = parser.peek() {
        match tok {
            Token::Star => { parser.consume(); let right = parse_factor(parser)?; left = left * right; if left.is_infinite() { return Err(format!("Error: to large to process! Max value: {}", MAX_STR)); } },
            Token::Slash => { parser.consume(); let right = parse_factor(parser)?; if right == 0.0 { return Err("Math Error: Divide by zero error!".to_string()); } left = left / right; if left.is_infinite() { return Err(format!("Error: to large to process! Max value: {}", MAX_STR)); } },
            _ => break,
        }
    }
    Ok(left)
}

fn parse_factor(parser: &mut Parser) -> Result<f64, String> {
    let mut left = parse_unary(parser)?;
    if let Some(Token::Caret) = parser.peek() {
        parser.consume();
        let right = parse_factor(parser)?;
        let res = left.powf(right);
        if res.is_nan() { return Err("Domain Error: Out of bounds!".to_string()); }
        if res.is_infinite() { return Err(format!("Error: to large to process! Max value: {}", MAX_STR)); }
        left = res;
    }
    Ok(left)
}

fn parse_unary(parser: &mut Parser) -> Result<f64, String> {
    if let Some(tok) = parser.peek() {
        match tok {
            Token::Plus => { parser.consume(); return parse_unary(parser); },
            Token::Minus => { parser.consume(); let v = parse_unary(parser)?; let res = -v; if res.is_infinite() { return Err(format!("Error: to large to process! Max value: {}", MAX_STR)); } return Ok(res); },
            _ => {},
        }
    }
    parse_postfix(parser)
}

fn parse_postfix(parser: &mut Parser) -> Result<f64, String> {
    let mut val = parse_primary(parser)?;
    while let Some(Token::Bang) = parser.peek() {
        parser.consume();
        if val < 0.0 || val.fract() != 0.0 {
            return Err("Domain Error: Out of bounds!".to_string());
        }
        let n = val as u64;
        let mut res: f64 = 1.0;
        for i in 2..=n {
            res *= i as f64;
            if res.is_infinite() {
                return Err(format!("Error: to large to process! Max value: {}", MAX_STR));
            }
        }
        val = res;
    }
    Ok(val)
}

fn parse_primary(parser: &mut Parser) -> Result<f64, String> {
    let tok = parser.peek().cloned();
    match tok {
        Some(Token::Number(v)) => { parser.consume(); if v.is_infinite() { return Err(format!("Error: to large to process! Max value: {}", MAX_STR)); } Ok(v) },
        Some(Token::ConstPi) => { parser.consume(); Ok(std::f64::consts::PI) },
        Some(Token::ConstE) => { parser.consume(); Ok(std::f64::consts::E) },
        Some(Token::Underscore) => {
            parser.consume();
            if let Some(prev) = parser.prev_ans { Ok(prev) } else { Err("Syntax Error: No previous answer!".to_string()) }
        },
        Some(Token::Func(name)) => {
            let func_name = name.clone();
            parser.consume();
            match parser.peek() {
                Some(Token::LParen) => {},
                _ => return Err(format!("Syntax Error: Function '{}' expected parentheses", func_name)),
            }
            parser.consume();
            let mut args = Vec::new();
            if let Some(Token::RParen) = parser.peek() {
            } else {
                if let Some(Token::Comma) = parser.peek() {
                    return Err(format!("Parser Error: To few arguments for function, need {}", if is_one_arg_func(&func_name) {1} else {2}));
                }
                let first = parse_expression(parser)?;
                args.push(first);
                while let Some(Token::Comma) = parser.peek() {
                    parser.consume();
                    if let Some(Token::RParen) = parser.peek() { break; }
                    if let Some(Token::Comma) = parser.peek() {
                        return Err(format!("Parser Error: To few arguments for function, need {}", if is_one_arg_func(&func_name) {1} else {2}));
                    }
                    let next_arg = parse_expression(parser)?;
                    args.push(next_arg);
                }
            }
            match parser.peek() {
                Some(Token::RParen) => { parser.consume(); },
                _ => return Err("Syntax Error: Mismatched parentheses!".to_string()),
            }
            if is_one_arg_func(&func_name) {
                if args.len() < 1 { return Err(format!("Parser Error: To few arguments for function, need 1")); }
                if args.len() > 1 { return Err("Parser Error: Too many operators, too few operands".to_string()); }
            } else if is_two_arg_func(&func_name) {
                if args.len() < 2 { return Err(format!("Parser Error: To few arguments for function, need 2")); }
                if args.len() > 2 { return Err("Parser Error: Too many operators, too few operands".to_string()); }
            }
            eval_func(&func_name, &args, parser.angle)
        },
        Some(Token::Ident(name)) => {
            let ident_clone = name.clone();
            let next_is_lparen = if parser.pos+1 < parser.tokens.len() {
                matches!(parser.tokens[parser.pos+1], Token::LParen)
            } else { false };
            if next_is_lparen {
                return Err(format!("Syntax Error: Unknown function '{}'", ident_clone));
            } else {
                return Err("Parser Error: Too many operators, too few operands".to_string());
            }
        },
        Some(Token::LParen) => {
            parser.consume();
            let val = parse_expression(parser)?;
            match parser.peek() {
                Some(Token::RParen) => { parser.consume(); Ok(val) },
                _ => Err("Syntax Error: Mismatched parentheses!".to_string()),
            }
        },
        Some(Token::RParen) => Err("Syntax Error: Mismatched parentheses!".to_string()),
        Some(Token::Comma) => Err("Syntax Error: Mismatched parentheses!".to_string()),
        Some(Token::Plus) | Some(Token::Minus) | Some(Token::Star) | Some(Token::Slash) | Some(Token::Caret) | Some(Token::Bang) => Err("Parser Error: Too many operators, too few operands".to_string()),
        None => Err("Parser Error: Too many operators, too few operands".to_string()),
    }
}

fn eval_func(name: &str, args: &[f64], angle: i32) -> Result<f64, String> {
    let to_rad = |x: f64| {
        match angle {
            0 => x * std::f64::consts::PI / 180.0,
            1 => x,
            2 => x * std::f64::consts::PI / 180.0,
            _ => x * std::f64::consts::PI / 180.0,
        }
    };
    let res = match name {
        "sin" => { let x=args[0]; to_rad(x).sin() },
        "cos" => { let x=args[0]; to_rad(x).cos() },
        "tan" => { let x=args[0]; to_rad(x).tan() },
        "csc" => { let x=args[0]; let s = to_rad(x).sin(); if s==0.0 { return Err("Domain Error: Out of bounds!".to_string()); } 1.0/s },
        "sec" => { let x=args[0]; let c = to_rad(x).cos(); if c==0.0 { return Err("Domain Error: Out of bounds!".to_string()); } 1.0/c },
        "cot" => { let x=args[0]; let s = to_rad(x).sin(); if s==0.0 { return Err("Domain Error: Out of bounds!".to_string()); } to_rad(x).cos()/s },
        "sinh" => args[0].sinh(),
        "cosh" => args[0].cosh(),
        "tanh" => args[0].tanh(),
        "asin" => { let x=args[0]; if x<-1.0||x>1.0{return Err("Domain Error: Out of bounds!".to_string());} x.asin() },
        "acos" => { let x=args[0]; if x<-1.0||x>1.0{return Err("Domain Error: Out of bounds!".to_string());} x.acos() },
        "atan" => args[0].atan(),
        "acsc" => { let x=args[0]; if x.abs()<1.0{ return Err("Domain Error: Out of bounds!".to_string()); } (1.0/x).asin() },
        "asec" => { let x=args[0]; if x.abs()<1.0{ return Err("Domain Error: Out of bounds!".to_string()); } (1.0/x).acos() },
        "acot" => { let x=args[0]; if x==0.0 { return Ok(std::f64::consts::PI/2.0); } (1.0/x).atan() },
        "ln" => { let x=args[0]; if x<=0.0{return Err("Domain Error: Out of bounds!".to_string());} x.ln() },
        "log2" => { let x=args[0]; if x<=0.0{return Err("Domain Error: Out of bounds!".to_string());} x.log2() },
        "log10" => { let x=args[0]; if x<=0.0{return Err("Domain Error: Out of bounds!".to_string());} x.log10() },
        "sqrt" => { let x=args[0]; if x<0.0{return Err("Domain Error: Out of bounds!".to_string());} x.sqrt() },
        "ceil" => args[0].ceil(),
        "floor" => args[0].floor(),
        "abs" => args[0].abs(),
        "exp" => { let r=args[0].exp(); if r.is_infinite(){return Err("Domain Error: Out of bounds!".to_string());} r },
        "deg" => args[0]*180.0/std::f64::consts::PI,
        "rad" => args[0]*std::f64::consts::PI/180.0,
        "log" => { let x=args[0]; let base=args[1]; if x<=0.0||base<=0.0||base==1.0{return Err("Domain Error: Out of bounds!".to_string());} x.log(base) },
        "nroot" => { let x=args[0]; let n=args[1]; if n==0.0{return Err("Domain Error: Out of bounds!".to_string());} if x<0.0{return Err("Domain Error: Out of bounds!".to_string());} x.powf(1.0/n) },
        _ => return Err(format!("Syntax Error: Unknown function '{}'", name)),
    };
    if res.is_nan() { return Err("Domain Error: Out of bounds!".to_string()); }
    if res.is_infinite() { return Err(format!("Error: to large to process! Max value: {}", MAX_STR)); }
    if res.abs() > 1.7976931348623157e308 { return Err(format!("Error: to large to process! Max value: {}", MAX_STR)); }
    Ok(res)
}

fn balance_parens(s: &str) -> Result<String, String> {
    let open = s.chars().filter(|&c| c=='(').count();
    let close = s.chars().filter(|&c| c==')').count();
    if close > open { Err("Syntax Error: Mismatched parentheses!".to_string()) }
    else if open > close { Ok(format!("{}{}", s, ")".repeat(open-close))) }
    else { Ok(s.to_string()) }
}

fn eval_input(input: &str, prev_ans: Option<f64>, angle: i32) -> Result<f64, String> {
    let trimmed = input.trim();
    if trimmed.is_empty() { return Err("EMPTY".to_string()); }
    let balanced = balance_parens(trimmed)?;
    let tokens = lex(&balanced)?;
    if tokens.is_empty() { return Err("Parser Error: Too many operators, too few operands".to_string()); }
    let with_mul = insert_implicit_mul(tokens);
    let mut parser = Parser { tokens: with_mul, pos: 0, prev_ans, angle };
    let result = parse_expression(&mut parser)?;
    if parser.pos < parser.tokens.len() {
        match &parser.tokens[parser.pos] {
            Token::RParen => return Err("Syntax Error: Mismatched parentheses!".to_string()),
            Token::Comma => return Err("Syntax Error: Mismatched parentheses!".to_string()),
            _ => return Err("Parser Error: Too many operators, too few operands".to_string()),
        }
    }
    Ok(result)
}

fn main() {
